  const [codePart, commentPart] = splitOffComment(raw);
  let code = escapeHtml(codePart);
  code = code.replace(
    /^(\s*)(- )?([\w\-\.][\w\-\.\s\[\]]*?)(:)(?=\s|$)/,
    (m, ws, marker, key, colon) => {
      const dash = marker ? `<span class="dash">- </span>` : "";
      return `${ws}${dash}<span class="key">${key}</span>${colon}`;
    }
  );
  code = code.replace(/^(\s*)(- )(?!<span)/, (m, ws) => `${ws}<span class="dash">- </span>`);
  code = code.replace(/"[^"]*"/g, m => `<span class="str">${m}</span>`);
  code = code.replace(/\b(true|false)\b/g, '<span class="bool">$1</span>');
  code = code.replace(
    /(^|[\s,\[\{:])(-?\d+(?:\.\d+)?)(?=[\s,\]\}]|$)/g,
    (m, pre, n) => `${pre}<span class="num">${n}</span>`
  );
  let html = code;
  if (commentPart) html += `<span class="cmt">${escapeHtml(commentPart)}</span>`;
  return html;
}

