// ------------------------------------------------------------------
// Registry: pair each `- name: "X"` with its following `type: "Y"` at the
// matching indentation, giving a name → {path, type, line} lookup.
//
// Additionally, for SPECIES_MAP entries, walk into the nested `sources:`
// block and record each source key's line as SOURCE_REGISTRY[mapName][srcKey].
// This lets compound references — `species_map: { mechanism: X, source: Y }`
// — resolve to the exact `Y:` line inside the mechanism file.
// ------------------------------------------------------------------
const REGISTRY = {};
const SOURCE_REGISTRY = {};
const COUNTS = {};
for (const path in FILES) {
  const lines = FILES[path].split("\n");
  let pendingName = null;
  let pendingLine = -1;
  let pendingIndent = -1;
  let currentMap = null;          // active SPECIES_MAP entry name
  let currentMapIndent = -1;      // entry-field indent (inside the map entry)
  let inSourcesBlock = false;
  let sourcesChildIndent = -1;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const nm = line.match(/^(\s*)-\s+name:\s*"([^"]+)"/);
    if (nm) {
      pendingName = nm[2];
      pendingLine = i;
      pendingIndent = nm[1].length + 2;
      currentMap = null;
      inSourcesBlock = false;
      continue;
    }
    if (pendingName) {
      const tm = line.match(/^(\s*)type:\s*"([^"]+)"/);
      if (tm && tm[1].length === pendingIndent) {
        REGISTRY[pendingName] = { path, type: tm[2], line: pendingLine };
        COUNTS[tm[2]] = (COUNTS[tm[2]] || 0) + 1;
        if (tm[2] === "SPECIES_MAP") {
          currentMap = pendingName;
          currentMapIndent = pendingIndent;
          SOURCE_REGISTRY[currentMap] = { path, line: pendingLine, sources: {} };
        }
        pendingName = null;
        continue;
      } else if (/^\S/.test(line)) {
        pendingName = null;
      }
    }
    if (currentMap) {
      // Terminate when another top-level list item or an unindented line appears.
      if (/^\S/.test(line) || /^\s*-\s+name:/.test(line)) {
        currentMap = null;
        inSourcesBlock = false;
        continue;
      }
      const srcHeader = line.match(/^(\s*)sources:\s*$/);
      if (srcHeader && srcHeader[1].length === currentMapIndent) {
        inSourcesBlock = true;
        sourcesChildIndent = currentMapIndent + 2;
        continue;
      }
      if (inSourcesBlock) {
        const keyMatch = line.match(/^(\s*)([\w\-\.]+):\s*$/);
        if (keyMatch && keyMatch[1].length === sourcesChildIndent) {
          SOURCE_REGISTRY[currentMap].sources[keyMatch[2]] = { path, line: i };
        }
        // Leaving the sources block when indent drops back to map-entry level.
        if (/^\s*\S/.test(line) && (line.match(/^(\s*)/)[1].length <= currentMapIndent)) {
          inSourcesBlock = false;
        }
      }
    }
  }
}

