}

// ------------------------------------------------------------------
// Syntax highlighting — line-oriented regex pipeline. Input is YAML text
// from the FILES constant above; output is HTML built from escaped input
// plus styling spans we construct ourselves. No user input ever reaches
// the HTML-parsing path.
// ------------------------------------------------------------------
function escapeHtml(s) {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function splitOffComment(line) {
  let inStr = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (c === '"') inStr = !inStr;
    if (c === "#" && !inStr) return [line.slice(0, i), line.slice(i)];
  }
  return [line, ""];
}

// Tokenize the value portion of a line (everything after `KEY:` or the
// leading `- ` marker). Walks char-by-char so we never re-scan text
// we've already wrapped in <span> tags — the multi-pass regex approach
// used previously matched the `"key"` attribute inside emitted spans
// and produced malformed nested output.
function highlightValues(s) {
  let out = "";
  let i = 0;
  while (i < s.length) {
    const c = s[i];
    if (c === '"') {
      let j = i + 1;
      while (j < s.length && s[j] !== '"') j++;
      const end = j < s.length ? j + 1 : s.length;
      out += `<span class="str">${s.slice(i, end)}</span>`;
      i = end;
      continue;
    }
    const prev = i === 0 ? "" : s[i - 1];
    const tail = s.slice(i);
    const wordBoundary = i === 0 || /[\s,\[\{:]/.test(prev);
    if (wordBoundary) {
      const bm = tail.match(/^(true|false)\b/);
      if (bm) { out += `<span class="bool">${bm[0]}</span>`; i += bm[0].length; continue; }
      const nm = tail.match(/^-?\d+(?:\.\d+)?/);
      if (nm) { out += `<span class="num">${nm[0]}</span>`; i += nm[0].length; continue; }
    }
    out += c;
    i++;
  }
  return out;
}

function highlightLine(raw) {
  const [codePart, commentPart] = splitOffComment(raw);
  const escaped = escapeHtml(codePart);
  const m = escaped.match(
    /^(\s*)(- )?(?:([\w\-\.][\w\-\.\s\[\]]*?)(:)(?=\s|$))?([\s\S]*)$/
  );
  let out;
  if (!m) {
    out = highlightValues(escaped);
  } else {
    const [, ws, dash, key, colon, rest] = m;
    out = ws;
    if (dash) out += `<span class="dash">- </span>`;
    if (key) out += `<span class="key">${key}</span>${colon}`;
    out += highlightValues(rest);
  }
  if (commentPart) out += `<span class="cmt">${escapeHtml(commentPart)}</span>`;
  return out;
}

