function resolveSimpleRef(key, value) {
  if (key === "micm_config") {
    const cleaned = value.replace(/^\.\//, "");
    if (FILES[cleaned]) return { path: cleaned, anchor: "L1" };
    return null;
  }
  const entry = REGISTRY[value];
  if (!entry) return null;
  return { path: entry.path, anchor: "L" + (entry.line + 1) };
}

// For unquoted path list-items inside miem-files: / camp-files: blocks.
function rewriteIncludeLists(lines, linesHtml) {
  let inList = false;
  let listIndent = -1;
  for (let i = 0; i < lines.length; i++) {
    const raw = lines[i];
    const headerMatch = raw.match(/^(\s*)(miem-files|camp-files):\s*$/);
    if (headerMatch) { inList = true; listIndent = headerMatch[1].length; continue; }
    if (!inList) continue;
    const itemMatch = raw.match(/^(\s+)-\s+([^\s"#][^\s#]*?)(\s*(#.*)?)?$/);
    if (itemMatch && itemMatch[1].length > listIndent) {
      const relPath = itemMatch[2];
      const resolved = resolveIncludePath(relPath);
      if (FILES[resolved]) {
        const escPath = escapeHtml(relPath);
        linesHtml[i] = linesHtml[i].replace(
          escPath,
          `<a class="ref" href="#" data-path="${resolved}" data-anchor="L1">${escPath}<span class="tag">→ file</span></a>`
        );
      }
      continue;
    }
    if (!/^\s+(-|#|$)/.test(raw)) inList = false;
  }
  return linesHtml;
}

function resolveIncludePath(relPath) {
  if (FILES[relPath]) return relPath;
  for (const k of Object.keys(FILES)) {
    if (k.endsWith("/" + relPath)) return k;
  }
  return relPath;
}

// ------------------------------------------------------------------
// Rendering (DOM-safe: createElement + Range.createContextualFragment)
// ------------------------------------------------------------------
function fragmentFromHtml(html) {
  const range = document.createRange();
  range.selectNode(document.body);
  return range.createContextualFragment(html);
}

function renderFile(path) {
  const content = FILES[path];
  const rawLines = content.split("\n");
  if (rawLines.length && rawLines[rawLines.length - 1] === "") rawLines.pop();

  let linesHtml = rawLines.map(highlightLine).map(wireRefs);
  linesHtml = rewriteIncludeLists(rawLines, linesHtml);

  const code = document.getElementById("code");
  while (code.firstChild) code.removeChild(code.firstChild);
  linesHtml.forEach((h, i) => {
    const ln = i + 1;
    const row = document.createElement("div");
    row.className = "line";
    row.id = "L" + ln;
    const num = document.createElement("span");
    num.className = "ln";
    num.textContent = String(ln);
    row.appendChild(num);
    const txt = document.createElement("span");
    txt.className = "txt";
    if (h && h.length) {
      txt.appendChild(fragmentFromHtml(h));
    } else {
      txt.textContent = "\u00A0";
    }
    row.appendChild(txt);
    code.appendChild(row);
  });

  document.getElementById("path").textContent = path;
  renderEntries(path, content);

  code.querySelectorAll("a.ref").forEach(a => {
    a.addEventListener("click", e => {
      e.preventDefault();
      selectFile(a.getAttribute("data-path"), a.getAttribute("data-anchor"));
    });
  });
}

function renderEntries(path, content) {
  const entriesEl = document.getElementById("entries");
  while (entriesEl.firstChild) entriesEl.removeChild(entriesEl.firstChild);

  if (path === "mechanism/species.yaml") {
    const chemSpecs = (content.match(/type:\s*"CHEM_SPEC"/g) || []).length;
    appendTypeChip(entriesEl, "CHEM_SPEC", chemSpecs);
    return;
  }
  const byType = {};
  for (const name in REGISTRY) {
    if (REGISTRY[name].path !== path) continue;
    const t = REGISTRY[name].type;
    byType[t] = (byType[t] || 0) + 1;
  }
  const keys = Object.keys(byType);
  if (!keys.length) {
    entriesEl.textContent = "(include manifest)";
    return;
  }
  keys.forEach(t => appendTypeChip(entriesEl, t, byType[t]));
}

function appendTypeChip(parent, type, count) {
  const span = document.createElement("span");
  const dot = document.createElement("span");
  dot.className = "dot t-" + type;
  span.appendChild(dot);
  const label = document.createTextNode(count + " " + type);
  span.appendChild(label);
  parent.appendChild(span);
}

function flashLine(anchor) {
  if (!anchor) return;
  const el = document.getElementById(anchor);
  if (!el) return;
  el.scrollIntoView({ block: "center", behavior: "smooth" });
  el.classList.remove("highlight");
  void el.offsetWidth;
  el.classList.add("highlight");
  setTimeout(() => el.classList.remove("highlight"), 1600);
}

function selectFile(path, anchor) {
  if (!FILES[path]) return;
  document.querySelectorAll("nav .file").forEach(f => {
    f.classList.toggle("active", f.getAttribute("data-path") === path);
  });
  renderFile(path);
  if (anchor) requestAnimationFrame(() => flashLine(anchor));
  else document.querySelector("section.viewer").scrollTop = 0;
  history.replaceState(null, "", "#" + encodeURIComponent(path) + (anchor ? ":" + anchor : ""));
}

