      nm.textContent = f.split("/").pop();
      d.appendChild(nm);
      const count = entryByFile[f];
      if (count) {
        const b = document.createElement("span");
        b.className = "badge";
        b.textContent = String(count);
        d.appendChild(b);
      } else if (f === "mechanism/species.yaml") {
        const chemSpecs = (FILES[f].match(/type:\s*"CHEM_SPEC"/g) || []).length;
        const b = document.createElement("span");
        b.className = "badge";
        b.textContent = String(chemSpecs);
        d.appendChild(b);
      }
      d.addEventListener("click", () => selectFile(f));
      nav.appendChild(d);
    });
  });
}

function buildLegend() {
  const el = document.getElementById("legend");
  const order = ["EMISSION_SOURCE", "SPECIES_MAP", "DIURNAL_PROFILE", "VOC_PROFILE", "VERTICAL_PROFILE", "CHEM_SPEC"];
  const chemCount = (FILES["mechanism/species.yaml"].match(/type:\s*"CHEM_SPEC"/g) || []).length;
  order.forEach(t => {
    const chip = document.createElement("span");
    chip.className = "chip";
    chip.title = TYPE_LABEL[t] || t;
    const dot = document.createElement("span");
    dot.className = "dot t-" + t;
    chip.appendChild(dot);
    const name = document.createElement("b");
    name.textContent = t;
    chip.appendChild(name);
    const count = document.createElement("span");
    count.className = "count";
    count.textContent = String(t === "CHEM_SPEC" ? chemCount : (COUNTS[t] || 0));
    chip.appendChild(count);
    el.appendChild(chip);
  });
}

buildLegend();
buildNav();

const hash = decodeURIComponent(location.hash.replace(/^#/, ""));
const [hashPath, hashAnchor] = hash.split(":");
const initPath = (hashPath && FILES[hashPath]) ? hashPath : "miem.yaml";
selectFile(initPath, hashAnchor);
</script>
</body>
</html>

