(function buildInventoryRegistry() {
  const path = "miem.yaml";
  if (!FILES[path]) return;
  const lines = FILES[path].split("\n");
  let inInventories = false;
  let childIndent = -1;
  for (let i = 0; i < lines.length; i++) {
    const raw = lines[i];
    const header = raw.match(/^(\s*)inventories:\s*$/);
    if (header) {
      inInventories = true;
      childIndent = header[1].length + 2;   // one YAML indent deeper
      continue;
    }
    if (!inInventories) continue;
    if (/^\s*#/.test(raw) || /^\s*$/.test(raw)) continue;
    const leading = raw.match(/^(\s*)\S/);
    if (!leading) continue;
    if (leading[1].length < childIndent) {
      // Dropped back to the same or shallower indent as `inventories:` → done.
      inInventories = false;
      continue;
    }
    if (leading[1].length !== childIndent) continue;   // nested field, skip
    const km = raw.match(/^(\s*)([\w\-\.]+):\s*$/);
    if (km) INVENTORY_REGISTRY[km[2]] = { path, line: i };
  }
})();
for (const path in FILES) {
  const lines = FILES[path].split("\n");
  let pendingName = null;
  let pendingLine = -1;
  let pendingIndent = -1;
  let currentMap = null;          // active SPECIES_MAP entry name
  let currentMapIndent = -1;      // entry-field indent (inside the map entry)
  let inSourcesBlock = false;
  let sourcesChildIndent = -1;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const nm = line.match(/^(\s*)-\s+name:\s*"([^"]+)"/);
    if (nm) {
      pendingName = nm[2];
      pendingLine = i;
      pendingIndent = nm[1].length + 2;
      currentMap = null;
      inSourcesBlock = false;
      continue;
    }
    if (pendingName) {
      const tm = line.match(/^(\s*)type:\s*"([^"]+)"/);
      if (tm && tm[1].length === pendingIndent) {
        REGISTRY[pendingName] = { path, type: tm[2], line: pendingLine };
